import { useEffect, useState, type FormEvent } from 'react'
import {
  createExpense,
  fetchExpenses,
  ValidationError,
  type Expense,
} from './api'

export function App() {
  const [expenses, setExpenses] = useState<Expense[]>([])
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState<string | null>(null)

  const [label, setLabel] = useState('')
  const [amount, setAmount] = useState('')
  const [currency, setCurrency] = useState('EUR')
  const [errors, setErrors] = useState<Record<string, string>>({})
  const [formError, setFormError] = useState<string | null>(null)
  const [submitting, setSubmitting] = useState(false)

  useEffect(() => {
    const controller = new AbortController()
    fetchExpenses(controller.signal)
      .then(setExpenses)
      .catch((e: unknown) => {
        if (controller.signal.aborted) return
        setLoadError(e instanceof Error ? e.message : 'Failed to load expenses')
      })
      .finally(() => {
        if (!controller.signal.aborted) setLoading(false)
      })
    return () => controller.abort()
  }, [])

  async function onSubmit(e: FormEvent) {
    e.preventDefault()
    if (submitting) return
    setSubmitting(true)
    setErrors({})
    setFormError(null)
    try {
      const created = await createExpense({
        label,
        amount: Number(amount),
        currency,
      })
      setExpenses((prev) => [...prev, created])
      setLabel('')
      setAmount('')
    } catch (err) {
      if (err instanceof ValidationError) {
        setErrors(err.errors)
      } else {
        setFormError(
          err instanceof Error ? err.message : 'Failed to submit expense',
        )
      }
    } finally {
      setSubmitting(false)
    }
  }

  const field = (name: string, text: string, input: React.ReactNode) => (
    <div>
      <label>
        {text} {input}
      </label>
      {errors[name] && <div role="alert">{errors[name]}</div>}
    </div>
  )

  return (
    <main>
      <h1>My expenses</h1>
      {loading && <p>Loading…</p>}
      {loadError && <p role="alert">{loadError}</p>}
      {!loading && !loadError && expenses.length === 0 && (
        <p>No expenses yet.</p>
      )}
      {expenses.length > 0 && (
        <ul>
          {expenses.map((x) => (
            <li key={x.id}>
              {x.label} — {x.amount.toFixed(2)} {x.currency} ({x.status})
            </li>
          ))}
        </ul>
      )}

      <h2>New expense</h2>
      <form onSubmit={onSubmit} noValidate>
        {field(
          'label',
          'Label',
          <input
            value={label}
            onChange={(e) => setLabel(e.target.value)}
            aria-invalid={!!errors.label}
          />,
        )}
        {field(
          'amount',
          'Amount',
          <input
            type="number"
            step="0.01"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            aria-invalid={!!errors.amount}
          />,
        )}
        {field(
          'currency',
          'Currency',
          <input
            value={currency}
            onChange={(e) => setCurrency(e.target.value)}
            aria-invalid={!!errors.currency}
          />,
        )}
        {formError && <p role="alert">{formError}</p>}
        <button type="submit" disabled={submitting}>
          {submitting ? 'Submitting…' : 'Submit'}
        </button>
      </form>
    </main>
  )
}
