          'currency',
          'Currency',
          <input
            value={currency}
            onChange={(e) => setCurrency(e.target.value)}
            aria-invalid={!!errors.currency}
          />,
        )}
        {formError && <p role="alert">{formError}</p>}
        <button type="submit" disabled={submitting}>
          {submitting ? 'Submitting…' : 'Submit'}
        </button>
      </form>
    </main>
  )
}
